import {drawAirFruit,drawAirBackdrop,drawAirSlash} from './air-slice-art.js';
import {coverMapping,clamp} from './air-slice-core.js';
export const AIR_COLORS=['#55cde7','#ffa573'];
export function fitAirCanvas(canvas){const r=canvas.getBoundingClientRect(),dpr=Math.min(globalThis.devicePixelRatio||1,1.5),w=Math.max(1,Math.round(r.width*dpr)),h=Math.max(1,Math.round(r.height*dpr));if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}return{w:r.width,h:r.height,logicalH:1600*r.height/Math.max(1,r.width)};}
export function renderAirSlice(canvas,world,{video=null,mirror=true,personScene=null,poses=[],calibration=false,showTracking=false,now=0,effects=.7,names=['Player 1','Player 2']}={}){
 const c=canvas.getContext('2d',{alpha:false}),w=world?.w||1600,h=world?.h||900;c.setTransform(canvas.width/w,0,0,canvas.height/h,0,0);c.clearRect(0,0,w,h);
 const virtual=!!personScene?.enabled,cutout=virtual?personScene.get(now):null;drawAirBackdrop(c,w,h,now);const source=virtual?cutout:video?.readyState>=2&&video.videoWidth?video:null;
 if(source){const m=coverMapping(source.videoWidth||source.width,source.videoHeight||source.height,w,h,mirror);c.save();if(virtual)c.globalAlpha=personScene.opacity??1;if(mirror){c.translate(w,0);c.scale(-1,1);}c.drawImage(source,m.ox,m.oy,m.dw,m.dh);c.restore();}
 if(calibration){c.save();c.setLineDash([15,15]);c.strokeStyle='#fff5de99';c.lineWidth=4;const count=names.length;for(let i=0;i<count;i++){const x=count===1?w*.5:w*(i===0?.28:.72);c.beginPath();c.roundRect(x-w*(count===1?.23:.19),h*.1,w*(count===1?.46:.38),h*.75,55);c.stroke();}c.restore();}
 for(const p of poses){if(!p)continue;const color=AIR_COLORS[p.owner];for(const a of p.arms){if(!a.valid)continue;c.save();c.strokeStyle=color;c.fillStyle=color;c.lineWidth=calibration||showTracking?8:3;c.lineCap='round';if(calibration||showTracking){c.beginPath();c.moveTo(a.shoulder.x,a.shoulder.y);c.lineTo(a.elbow.x,a.elbow.y);c.lineTo(a.wrist.x,a.wrist.y);c.lineTo(a.hand.x,a.hand.y);c.stroke();for(const q of [a.shoulder,a.elbow,a.wrist]){c.beginPath();c.arc(q.x,q.y,11,0,Math.PI*2);c.fill();}}c.beginPath();c.arc(a.hand.x,a.hand.y,calibration?20:12,0,Math.PI*2);c.fill();c.strokeStyle='#fff4dd';c.lineWidth=3;c.stroke();c.restore();}if(calibration||showTracking){c.save();const x=p.center.x,y=Math.max(115,p.center.y-p.width*.95);c.font='800 24px Outfit,sans-serif';const text=(p.owner+1)+' · '+names[p.owner],width=c.measureText(text).width+35;c.fillStyle='#173f49e6';c.beginPath();c.roundRect(x-width/2,y-23,width,42,17);c.fill();c.fillStyle=color;c.textAlign='center';c.fillText(text,x,y+6);c.restore();}}
 if(!world)return;
 c.save();if(world.shake&&effects>0)c.translate(Math.sin(now*.08)*world.shake*effects,Math.cos(now*.07)*world.shake*.5*effects);
 for(const p of world.pieces){c.save();c.globalAlpha=clamp(p.life/.6,0,1);c.translate(p.x,p.y);c.rotate(p.angle);drawAirFruit(c,p,{interior:true,side:p.side,time:now});c.restore();}
 for(const f of world.fruit){c.save();c.translate(f.x,f.y);c.rotate(f.angle);drawAirFruit(c,f,{time:now});c.restore();}
 for(const p of world.particles){c.save();c.globalAlpha=clamp(p.life*1.5,0,1);c.fillStyle=p.color;if(p.burst){c.strokeStyle=p.color;c.lineWidth=10;c.beginPath();c.arc(p.x,p.y,p.r*(1.5-p.life),0,Math.PI*2);c.stroke();}else{c.beginPath();c.ellipse(p.x,p.y,p.r,p.r*.68,Math.atan2(p.vy,p.vx),0,Math.PI*2);c.fill();}c.restore();}
 c.restore();for(const t of world.trails)drawAirSlash(c,t.points,AIR_COLORS[t.owner],clamp(t.life/.2,0,1));for(const l of world.labels){c.save();c.globalAlpha=clamp(l.life*2,0,1);c.textAlign='center';c.font='900 35px Outfit,sans-serif';c.strokeStyle='#23414b';c.lineWidth=7;c.lineJoin='round';c.strokeText(l.text,l.x,l.y);c.fillStyle=l.color;c.fillText(l.text,l.x,l.y);c.restore();}
 if(world.clock<world.freezeUntil){c.save();c.strokeStyle='#b8ecf5aa';c.lineWidth=14;c.strokeRect(7,7,w-14,h-14);c.restore();}
}
// Pointer ownership is chosen on DOWN and stays with that player across the whole screen.
export function bindAirPointers(canvas,{getWorld,isPlaying,onFeedback=()=>{},getActor=()=>0}={}){
 const pointers=new Map();let serial=0;const point=e=>{const r=canvas.getBoundingClientRect(),w=getWorld();return{x:(e.clientX-r.left)/r.width*w.w,y:(e.clientY-r.top)/r.height*w.h};};
 canvas.onpointerdown=e=>{const w=getWorld();if(!isPlaying()||!w||w.options.input==='camera')return;if(w.options.players===2&&w.options.competition==='versus'&&w.options.input==='touch'&&e.pointerType==='mouse'){onFeedback('Two-player touch needs simultaneous fingers. Choose alternating mouse play in Setup.');return;}e.preventDefault();const p=point(e),owner=w.options.players===1?0:w.options.input==='mouse-turns'?getActor():p.x<w.w/2?0:1;pointers.set(e.pointerId,{point:p,at:e.timeStamp,owner,stroke:++serial,direction:null});canvas.setPointerCapture(e.pointerId);};
 canvas.onpointermove=e=>{if(!isPlaying()){pointers.delete(e.pointerId);return;}const old=pointers.get(e.pointerId);if(!old)return;e.preventDefault();const samples=e.getCoalescedEvents?.();for(const sample of samples?.length?samples:[e]){const p=point(sample),dt=clamp(sample.timeStamp-old.at||16,8,260),dx=p.x-old.point.x,dy=p.y-old.point.y,len=Math.hypot(dx,dy),direction={x:dx/(len||1),y:dy/(len||1)};if(old.direction&&direction.x*old.direction.x+direction.y*old.direction.y<-.35||sample.timeStamp-old.at>230)old.stroke=++serial;getWorld().submit(old.owner,'pointer-'+e.pointerId,{from:old.point,to:p,dt,time:getWorld().clock,stroke:old.stroke});old.point=p;old.at=sample.timeStamp;if(len>4)old.direction=direction;}};
 const up=e=>{pointers.delete(e.pointerId);if(canvas.hasPointerCapture?.(e.pointerId))canvas.releasePointerCapture(e.pointerId);};canvas.onpointerup=up;canvas.onpointercancel=up;canvas.onlostpointercapture=up;
 return{pointers,clear(){for(const id of pointers.keys())if(canvas.hasPointerCapture?.(id))canvas.releasePointerCapture(id);pointers.clear();},dispose(){pointers.clear();canvas.onpointerdown=canvas.onpointermove=canvas.onpointerup=canvas.onpointercancel=canvas.onlostpointercapture=null;}};
}
